from pathlib import Path
import base64, re, subprocess

ROOT=Path(__file__).resolve().parents[2]
INDEX=ROOT/'index.html'
ASSET=ROOT/'assets/case-study-activity.jpg'
IMAGE_B64='''[... ELLIPSIZATION ...]'''

s=INDEX.read_text(encoding='utf-8')
old='var caseMap={"Case Study Apple":"Case Study：Apple","ケーススタディ Apple":"ケーススタディ：Apple","案例研究 Apple":"案例研究：Apple"};'
new='var caseMap={"Case Study Apple":"Case Study: APPLE","Case Study：Apple":"Case Study: APPLE","Case Study: Apple":"Case Study: APPLE","ケーススタディ Apple":"ケーススタディ：Apple","案例研究 Apple":"案例研究：Apple"};'
if old not in s:
    raise RuntimeError('Expected Case Study copy map not found')
s=s.replace(old,new,1)

old_apply='''  function apply(){\n    document.querySelectorAll("a,button").forEach(function(el){patchTextNodes(el,ctaMap);});\n    var scope=document.querySelector("#capabilities");\n    if(scope){scope.querySelectorAll("h1,h2,h3,.hierarchy-heading").forEach(function(el){patchTextNodes(el,caseMap);});}\n  }'''
new_apply='''  function ensureCasePhoto(scope){\n    if(!scope||scope.querySelector('img[data-case-study-activity="1"]'))return;\n    var heading=scope.querySelector('.ss-unified-heading[data-ss-section="capabilities"]');\n    if(!heading||!heading.parentNode)return;\n    var img=document.createElement("img");\n    img.src="assets/case-study-activity.jpg";\n    img.alt="";\n    img.loading="lazy";\n    img.setAttribute("data-case-study-activity","1");\n    img.style.display="block";\n    img.style.width="100%";\n    img.style.height="auto";\n    heading.insertAdjacentElement("afterend",img);\n  }\n  function apply(){\n    document.querySelectorAll("a,button").forEach(function(el){patchTextNodes(el,ctaMap);});\n    var scope=document.querySelector("#capabilities");\n    if(scope){\n      scope.querySelectorAll("h1,h2,h3,.hierarchy-heading").forEach(function(el){patchTextNodes(el,caseMap);});\n      ensureCasePhoto(scope);\n    }\n  }'''
if old_apply not in s:
    raise RuntimeError('Expected Case Study apply block not found')
s=s.replace(old_apply,new_apply,1)

INDEX.write_text(s,encoding='utf-8')
ASSET.parent.mkdir(parents=True,exist_ok=True)
ASSET.write_bytes(base64.b64decode(IMAGE_B64))

if ASSET.stat().st_size < 40000 or ASSET.read_bytes()[:2] != b'\xff\xd8':
    raise RuntimeError('Case Study image decode failed')
if s.count('data-case-study-activity') != 2:
    raise RuntimeError('Case Study photo hook count is unexpected')
if '"Case Study Apple":"Case Study: APPLE"' not in s:
    raise RuntimeError('Case Study colon copy missing')

m=re.search(r'<script id="requested-home-copy-overrides">(.*?)</script>',s,re.S)
if not m:
    raise RuntimeError('Requested home copy script missing')
check=ROOT/'.case-study-check.js'
check.write_text(m.group(1),encoding='utf-8')
subprocess.run(['node','--check',str(check)],cwd=ROOT,check=True)
check.unlink()
subprocess.run(['git','diff','--check'],cwd=ROOT,check=True)
print('Case Study title and activity photo patched')
